-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Captures planning inputs and detects changes while a search owns them.

local Constants = APR.NavigationConstants.Navigation

local nav = APR.navigation
local Shared = APR.navigation._helpers
local ContextCurrent = Shared.ContextCurrent
local CopyLocation = Shared.CopyLocation
local Distance = Shared.Distance
local FollowingManualCrossing = Shared.FollowingManualCrossing
local HasWalkingPath = Shared.HasWalkingPath
local Now = Shared.Now
local PlanningRequestCurrent = Shared.PlanningRequestCurrent
local Position = Shared.Position
local ReadableLocationValue = Shared.ReadableLocationValue
local SameAccess = Shared.SameAccess
local SameLocationFields = Shared.SameLocationFields
local TerrainRequired = Shared.TerrainRequired
local WalkingAccessReached = Shared.WalkingAccessReached
local WalkingPosition = Shared.WalkingPosition
local WalkingProjection = Shared.WalkingProjection
local WalkingProvider = Shared.WalkingProvider

function nav:IsDirectRouteValid(position)
    return self.state == "ready"
        and ContextCurrent(self._routedStepContext)
        and self._routeInputs
        and self._routeInputs.geometryRevision == APR.navigationGeometryRevision
        and self:IsObjectiveCurrent(self._routeInputs)
        and self.destination
        and position
        and not TerrainRequired(position, self.destination)
        and APR.NavigationData
        and APR.NavigationData:CanWalk(position, self.destination) == true
end--[[APR_DIAG]]; nav.IsDirectRouteValid = APRTrace("APR-Core/features/navigation/controller/NavigationPlanningInputs.lua:29:nav:IsDirectRouteValid#1", nav.IsDirectRouteValid)--[[/APR_DIAG]]

function nav:CapturePlanningInputs(step, position, context)
    if step._service then
        return {
            step = step,
            position = CopyLocation(position),
            startedAt = Now(),
            geometryRevision = APR.navigationGeometryRevision,
            indoors = IsIndoors and IsIndoors() == true or false,
        }
    end
    local definition = context.definition
    local sourceSteps = definition and (definition.steps or definition)
    local coord = step.Coord
    local coordValues = coord and CopyLocation(coord)
    local _, fallback = APR:GetCurrentRouteMapIDsAndName()
    local resolvedCoord, resolvedMap = APR:GetStepCoord(step, fallback)
    -- Ordinary objectives resolve to their authored coordinate. Share that
    -- immutable snapshot so freshness checks need only validate it once.
    local resolvedValues = resolvedCoord and CopyLocation(resolvedCoord)
    if coordValues and resolvedValues and rawequal(resolvedCoord, coord) then resolvedValues = coordValues end
    return {
        position = CopyLocation(position),
        indoors = IsIndoors and IsIndoors() == true or false,
        startedAt = Now(),
        geometryRevision = APR.navigationGeometryRevision,
        step = step,
        sourceSteps = sourceSteps,
        sourceStep = sourceSteps and sourceSteps[context.index],
        coord = coord,
        x = coordValues and coordValues.x,
        y = coordValues and coordValues.y,
        mapID = coordValues and coordValues.mapID,
        instanceID = coordValues and coordValues.instanceID,
        coordValues = coordValues,
        resolvedCoord = resolvedCoord,
        resolvedValues = resolvedValues,
        resolvedMap = resolvedMap,
        fallbackMap = fallback,
        coords = step.Coords,
        zone = step.Zone,
        zones = step.Zones,
        noArrow = step.NoArrow,
        waypoint = step.Waypoint,
        range = step.Range,
    }
end--[[APR_DIAG]]; nav.CapturePlanningInputs = APRTrace("APR-Core/features/navigation/controller/NavigationPlanningInputs.lua:42:nav:CapturePlanningInputs#2", nav.CapturePlanningInputs)--[[/APR_DIAG]]

function nav:IsObjectiveCurrent(inputs)
    if not inputs then return false end
    if inputs.step and inputs.step._service then return APR.Services and APR.Services:GetStep() == inputs.step end
    -- Peek avoids resolving the effective route or activating parallel steps.
    -- Scenario handlers can change the runtime target without advancing it.
    local step = inputs.step
    if inputs.step and inputs.step._navigationUnlock then
        step = APR.GetNavigationUnlockStep and APR:GetNavigationUnlockStep()
    elseif APR.PeekCurrentStep then
        step = APR:PeekCurrentStep()
    end
    if step ~= inputs.step then return false end
    local context = self._routedStepContext
    local definition = context and context.definition
    local sourceSteps = definition and (definition.steps or definition)
    if sourceSteps ~= inputs.sourceSteps or (sourceSteps and sourceSteps[context.index]) ~= inputs.sourceStep then
        return false
    end
    local coord = step and step.Coord
    if issecretvalue and issecretvalue(coord) then return false end
    if coord and (type(coord) ~= "table" or (APR.CanAccessTable and not APR:CanAccessTable(coord))) then
        return false
    end
    -- A scenario/transport override can become applicable without changing the
    -- authored coordinate. Resolve only this step, never its route/history or
    -- the navigation catalogue.
    local resolved, map = APR:GetStepCoord(step, inputs.fallbackMap)
    if
        not ReadableLocationValue(map)
        or map ~= inputs.resolvedMap
        or (resolved and not SameLocationFields(resolved, inputs.resolvedValues, Constants.LOCATION_FIELDS))
        or (not resolved and inputs.resolvedCoord)
    then
        return false
    end
    local sharedCoordinate = rawequal(coord, resolved) and rawequal(inputs.coordValues, inputs.resolvedValues)
    return rawequal(coord, inputs.coord)
        and (not coord or sharedCoordinate or SameLocationFields(coord, inputs.coordValues, Constants.LOCATION_FIELDS))
        and step.Coords == inputs.coords
        and step.Zone == inputs.zone
        and step.Zones == inputs.zones
        and step.NoArrow == inputs.noArrow
        and step.Waypoint == inputs.waypoint
        and step.Range == inputs.range
end--[[APR_DIAG]]; nav.IsObjectiveCurrent = APRTrace("APR-Core/features/navigation/controller/NavigationPlanningInputs.lua:89:nav:IsObjectiveCurrent#3", nav.IsObjectiveCurrent)--[[/APR_DIAG]]

function nav:HasPlanningInputsChanged(position, verifiedWalkingCandidate)
    local inputs = self._routeInputs
    if not inputs or not inputs.position then return true end
    if not self:IsObjectiveCurrent(inputs) then return true end
    if self.waypointPendingLeg and self.waypointPendingLeg.before and self.search then return false end
    if not position then return true end
    if not self.dirty and self:IsNavigating() and FollowingManualCrossing(self:GetActiveStep(), position) then
        return false
    end
    if inputs.position.indoors ~= position.indoors then return true end
    local indoors = IsIndoors and IsIndoors() == true or false
    local geometryChanged = inputs.geometryRevision ~= APR.navigationGeometryRevision
    local indoorsChanged = inputs.indoors ~= indoors
    if not SameAccess(position, inputs.position) or geometryChanged or indoorsChanged then
        local step = self:IsNavigating() and self:GetActiveStep()
        local data = APR.NavigationData
        if
            self.dirty
            or not (data and data.profile == "forever" and data.IsSameAccessRegion and HasWalkingPath(step))
            or (position.uiMapID == inputs.position.uiMapID and (geometryChanged or not indoorsChanged))
            or position.isInstance ~= inputs.position.isInstance
            or data:IsSameAccessRegion(position, inputs.position) ~= true
            or data:CanWalk(position, step.to) ~= true
        then
            return true
        end
        local provider = WalkingProvider()
        local nextPoint = self:GetGuidanceTarget()
        local observed = WalkingPosition(position, provider, step)
        local join = not indoors and step.walkingFollow and step.walkingFollow.aim and "outdoor" or true
        if
            not (
                provider
                and provider.RequiresWalkingProof
                and provider:RequiresWalkingProof(observed, nextPoint)
                and provider.CanFollowWalkingSegment
                and provider:CanFollowWalkingSegment(observed, nextPoint, join) == true
            )
        then
            return true
        end
        -- Re-anchor the observation while preserving the route and its cursor.
        inputs.position, inputs.indoors, inputs.geometryRevision = position, indoors, APR.navigationGeometryRevision
        return false
    end
    -- Phase/quest access can close without changing the point's scalar fields.
    -- Recheck this direct proof only; it does not prepare or scan the catalogue.
    if
        self.state == "ready"
        and self.destination
        and APR.NavigationData
        and APR.NavigationData:CanWalk(position, self.destination) ~= true
    then
        return true
    end
    -- Walking around one objective does not alter the transport graph. Revisit
    -- the choice after meaningful displacement, while map and access changes
    -- bypass this movement allowance immediately.
    if self.search or verifiedWalkingCandidate then return false end
    if self.state == "waiting_data" and self.reason == "terrain_origin" then
        local previous = inputs.position
        if position.z ~= previous.z then return true end
        if position.x == previous.x and position.y == previous.y then return false end
        if inputs.waitingForWalkingFloor then return Distance(position, previous) >= 1 end
        local provider = WalkingProvider()
        return not (provider and provider.IsSameWalkingCell and provider:IsSameWalkingCell(previous, position))
    end
    local step = self:IsNavigating() and self:GetActiveStep()
    local data = APR.NavigationData
    local moved = Distance(position, self.waypointApproach and self.waypointApproach.observation or inputs.position)
    if Now() - inputs.startedAt < Constants.MOVEMENT_REPLAN_SECONDS then return false end
    if
        HasWalkingPath(step)
        and not self.walkingPrefix
        and not self.travelPrefix
        and data
        and data.profile == "forever"
        and data.CanWalk
        and data:CanWalk(position, step.to) == true
    then
        local follow = step.walkingFollow
        if
            follow
            and follow.geometry == APR.navigationGeometryRevision
            and SameAccess(position, follow.position)
            and (position.z == nil or position.z == follow.position.z)
            and Distance(position, follow.position) <= 2
        then
            if follow.aim then return false end
            if follow.off > Constants.WALK_STRAY_DISTANCE or follow.missed then
                return moved >= Constants.WALK_ARRIVAL_RADIUS
            end
        end
        if moved < Constants.MOVEMENT_REPLAN_YARDS then return false end
        local cursor = step.pathCursor or 2
        local target, previous = step.path[cursor], step.path[cursor - 1]
        if previous and target then
            local _, offset = WalkingProjection(position, previous, target)
            local provider = WalkingProvider()
            if
                offset <= Constants.WALK_POINT_RADIUS ^ 2
                and provider
                and provider.CanFollowWalkingSegment
                and provider:CanFollowWalkingSegment(WalkingPosition(position, provider, step), target, true)
                    == true
            then
                -- Movement along the published corridor needs no new transport search.
                inputs.position, inputs.startedAt = position, Now()
                return false
            end
        end
    end
    return moved >= Constants.MOVEMENT_REPLAN_YARDS
end--[[APR_DIAG]]; nav.HasPlanningInputsChanged = APRTrace("APR-Core/features/navigation/controller/NavigationPlanningInputs.lua:135:nav:HasPlanningInputsChanged#4", nav.HasPlanningInputsChanged)--[[/APR_DIAG]]

function nav:RefreshStalePlanningInputs()
    local inputs, context, destination, start = self._routeInputs, self.context, self.destination, self.start
    local generation, job = self.generation, self.search
    local position = Position()
    local retained = self:CaptureRetainedArrow(position)
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    local hadGuidance = inputs and self:IsObjectiveCurrent(inputs) and (inputs.hadGuidance or self:IsNavigating())
    local active = self:GetActiveStep()
    if hadGuidance and HasWalkingPath(active) and inputs.geometryRevision == APR.navigationGeometryRevision then
        local provider = WalkingProvider()
        local nextPoint = self:GetGuidanceTarget()
        local observed = WalkingPosition(position, provider, active)
        local join = active.walkingFollow and active.walkingFollow.aim and "outdoor" or true
        if
            provider
            and provider.CanFollowWalkingSegment
            and WalkingAccessReached(observed, nextPoint, nil, provider)
            and provider:CanFollowWalkingSegment(observed, nextPoint, join) == true
            and self:IsItineraryValid()
        then
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
            self:DiscardCandidate("planning_inputs_changed")
            self:ForceRefresh("planning_inputs_changed")
            self:RequestUpdate()
            return
        end
    end
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    self:Cancel("replan", retained ~= nil)
    if inputs then inputs.hadGuidance = hadGuidance or nil end
    self._routeInputs, self.context, self._routedStepContext = inputs, context, context
    self.destination, self.start, self.retainedArrow = destination, start, retained
    self.state, self.zoneReady, APR.IsInRouteZone = "planning", false, false
    self:ForceRefresh("planning_inputs_changed")
    self:Render()
    self:RequestUpdate()
end--[[APR_DIAG]]; nav.RefreshStalePlanningInputs = APRTrace("APR-Core/features/navigation/controller/NavigationPlanningInputs.lua:249:nav:RefreshStalePlanningInputs#5", nav.RefreshStalePlanningInputs)--[[/APR_DIAG]]
